[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800&family=Poppins:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --green-primary: #2D6A4F;
      --green-dark: #1e4a38;
      --orange-accent: #F4A261;
      --orange-dark: #e08c4a;
      --cream-bg: #FEFAE0;
      --cream-light: #fffef7;
      --white: #ffffff;
      --text-dark: #2c3e2d;
      --text-muted: #5a6b5c;
      --shadow-sm: 0 2px 8px rgba(45, 106, 79, 0.08);
      --shadow-md: 0 4px 16px rgba(45, 106, 79, 0.12);
      --shadow-lg: 0 8px 32px rgba(45, 106, 79, 0.16);
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 20px;
      --radius-xl: 28px;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Poppins', sans-serif;
      background-color: var(--cream-bg);
      color: var(--text-dark);
      line-height: 1.6;
      overflow-x: hidden;
    }

    h1, h2, h3, h4, h5, h6 {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      line-height: 1.2;
    }

    /* Header */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      background: var(--white);
      box-shadow: var(--shadow-sm);
      z-index: 1000;
      padding: 0 24px;
    }

    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      text-decoration: none;
      color: var(--green-primary);
    }

    .logo-icon {
      width: 44px;
      height: 44px;
      background: var(--green-primary);
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg {
      width: 28px;
      height: 28px;
      fill: var(--white);
    }

    .logo-text {
      font-family: 'Nunito', sans-serif;
      font-size: 1.5rem;
      font-weight: 800;
    }

    .nav {
      display: flex;
      gap: 32px;
    }

    .nav a {
      text-decoration: none;
      color: var(--text-dark);
      font-weight: 500;
      font-size: 0.95rem;
      padding: 8px 0;
      position: relative;
      transition: color 0.2s;
    }

    .nav a::after {
      content: '';
      position: absolute;
      bottom: 0;
      left: 0;
      width: 0;
      height: 2px;
      background: var(--orange-accent);
      transition: width 0.3s ease;
    }

    .nav a:hover {
      color: var(--green-primary);
    }

    .nav a:hover::after {
      width: 100%;
    }

    .mobile-menu-btn {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
    }

    /* Hero Section */
    .hero {
      padding: 140px 24px 80px;
      background: linear-gradient(135deg, var(--cream-bg) 0%, var(--cream-light) 100%);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(244, 162, 97, 0.15) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }

    .hero-content {
      position: relative;
      z-index: 1;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--white);
      padding: 8px 16px;
      border-radius: 50px;
      font-size: 0.85rem;
      font-weight: 500;
      color: var(--green-primary);
      box-shadow: var(--shadow-sm);
      margin-bottom: 24px;
    }

    .hero h1 {
      font-size: 3.5rem;
      color: var(--green-primary);
      margin-bottom: 20px;
      letter-spacing: -0.02em;
    }

    .hero-subtitle {
      font-size: 1.15rem;
      color: var(--text-muted);
      margin-bottom: 36px;
      max-width: 480px;
    }

    .hero-buttons {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 14px 28px;
      border-radius: var(--radius-lg);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      text-decoration: none;
      cursor: pointer;
      border: none;
      transition: all 0.25s ease;
    }

    .btn-primary {
      background: var(--green-primary);
      color: var(--white);
      box-shadow: 0 4px 14px rgba(45, 106, 79, 0.3);
    }

    .btn-primary:hover {
      background: var(--green-dark);
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(45, 106, 79, 0.35);
    }

    .btn-secondary {
      background: var(--white);
      color: var(--green-primary);
      border: 2px solid var(--green-primary);
    }

    .btn-secondary:hover {
      background: var(--green-primary);
      color: var(--white);
      transform: translateY(-2px);
    }

    .hero-image {
      position: relative;
    }

    .hero-image-main {
      width: 100%;
      height: 420px;
      background: var(--white);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow-lg);
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
    }

    .hero-image-main img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .hero-image-placeholder {
      width: 100%;
      height: 100%;
      background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 50%, #a5d6a7 100%);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 16px;
      color: var(--green-primary);
    }

    .hero-image-placeholder svg {
      width: 80px;
      height: 80px;
      fill: var(--green-primary);
      opacity: 0.6;
    }

    /* Stats Banner */
    .stats-banner {
      background: var(--green-primary);
      padding: 48px 24px;
      position: relative;
      overflow: hidden;
    }

    .stats-banner::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.05'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
      opacity: 0.5;
    }

    .stats-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
      position: relative;
      z-index: 1;
    }

    .stat-item {
      text-align: center;
      color: var(--white);
    }

    .stat-number {
      font-family: 'Nunito', sans-serif;
      font-size: 3rem;
      font-weight: 800;
      line-height: 1;
      margin-bottom: 8px;
    }

    .stat-label {
      font-size: 0.95rem;
      opacity: 0.9;
    }

    /* Featured Products Carousel */
    .featured-products {
      padding: 80px 24px;
      background: var(--cream-light);
    }

    .section-header {
      max-width: 1280px;
      margin: 0 auto 40px;
      text-align: center;
    }

    .section-title {
      font-size: 2.25rem;
      color: var(--green-primary);
      margin-bottom: 12px;
    }

    .section-subtitle {
      color: var(--text-muted);
      font-size: 1.05rem;
    }

    .carousel-container {
      max-width: 1280px;
      margin: 0 auto;
      position: relative;
    }

    .carousel-viewport {
      overflow: hidden;
      margin: 0 48px;
    }

    .carousel-track {
      display: flex;
      gap: 24px;
      transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: var(--white);
      border: none;
      box-shadow: var(--shadow-md);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all 0.25s ease;
      z-index: 10;
    }

    .carousel-btn:hover {
      background: var(--green-primary);
    }

    .carousel-btn:hover svg {
      stroke: var(--white);
    }

    .carousel-btn svg {
      width: 24px;
      height: 24px;
      stroke: var(--green-primary);
      stroke-width: 2.5;
      fill: none;
    }

    .carousel-btn.prev {
      left: 0;
    }

    .carousel-btn.next {
      right: 0;
    }

    .product-card {
      flex: 0 0 calc(25% - 18px);
      min-width: 260px;
      background: var(--white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-sm);
      overflow: hidden;
      transition: all 0.3s ease;
    }

    .product-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-lg);
    }

    .product-image {
      width: 100%;
      height: 180px;
      background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .product-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .product-image-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 8px;
      color: var(--green-primary);
    }

    .product-image-placeholder svg {
      width: 48px;
      height: 48px;
      fill: var(--green-primary);
      opacity: 0.5;
    }

    .product-info {
      padding: 20px;
    }

    .product-name {
      font-family: 'Nunito', sans-serif;
      font-size: 1.1rem;
      font-weight: 700;
      color: var(--text-dark);
      margin-bottom: 6px;
    }

    .product-desc {
      font-size: 0.85rem;
      color: var(--text-muted);
      margin-bottom: 12px;
      line-height: 1.4;
    }

    .product-price {
      font-family: 'Nunito', sans-serif;
      font-size: 1.25rem;
      font-weight: 800;
      color: var(--green-primary);
    }

    /* Seasonal Picks */
    .seasonal-picks {
      padding: 80px 24px;
      background: var(--cream-bg);
    }

    .seasonal-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .seasonal-title {
      font-size: 2.25rem;
      color: var(--green-primary);
      margin-bottom: 8px;
    }

    .seasonal-grid {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 24px;
    }

    .seasonal-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-sm);
      overflow: hidden;
      display: flex;
      gap: 20px;
      padding: 20px;
      transition: all 0.3s ease;
    }

    .seasonal-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-4px);
    }

    .seasonal-image {
      width: 100px;
      height: 100px;
      border-radius: var(--radius-md);
      background: linear-gradient(135deg, #fff8e1 0%, #ffecb3 100%);
      flex-shrink: 0;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .seasonal-image svg {
      width: 40px;
      height: 40px;
      fill: var(--orange-accent);
    }

    .seasonal-content {
      flex: 1;
    }

    .seasonal-name {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1.05rem;
      color: var(--text-dark);
      margin-bottom: 4px;
    }

    .seasonal-desc {
      font-size: 0.85rem;
      color: var(--text-muted);
      margin-bottom: 8px;
    }

    .seasonal-price {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      color: var(--green-primary);
      font-size: 1.1rem;
    }

    /* Categories */
    .categories {
      padding: 80px 24px;
      background: var(--white);
    }

    .categories-grid {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 20px;
    }

    .category-card {
      position: relative;
      height: 200px;
      border-radius: var(--radius-lg);
      overflow: hidden;
      cursor: pointer;
      box-shadow: var(--shadow-sm);
    }

    .category-bg {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: transform 0.4s ease;
    }

    .category-card:nth-child(1) .category-bg {
      background: linear-gradient(135deg, #ff8a65 0%, #ffb74d 100%);
    }

    .category-card:nth-child(2) .category-bg {
      background: linear-gradient(135deg, #66bb6a 0%, #a5d6a7 100%);
    }

    .category-card:nth-child(3) .category-bg {
      background: linear-gradient(135deg, #42a5f5 0%, #90caf9 100%);
    }

    .category-card:nth-child(4) .category-bg {
      background: linear-gradient(135deg, #ab47bc 0%, #ce93d8 100%);
    }

    .category-card:nth-child(5) .category-bg {
      background: linear-gradient(135deg, #ffa726 0%, #ffd95b 100%);
    }

    .category-card:hover .category-bg {
      transform: scale(1.08);
    }

    .category-icon {
      width: 64px;
      height: 64px;
      background: var(--white);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-md);
      transition: transform 0.3s ease;
    }

    .category-card:hover .category-icon {
      transform: scale(1.1);
    }

    .category-icon svg {
      width: 32px;
      height: 32px;
      fill: var(--green-primary);
    }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: rgba(45, 106, 79, 0.85);
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0;
      transition: opacity 0.3s ease;
    }

    .category-card:hover .category-overlay {
      opacity: 1;
    }

    .category-overlay-text {
      font-family: 'Nunito', sans-serif;
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--white);
      text-align: center;
      padding: 16px;
    }

    /* Store Locator */
    .store-locator {
      padding: 80px 24px;
      background: linear-gradient(135deg, var(--cream-bg) 0%, var(--cream-light) 100%);
    }

    .locator-card {
      max-width: 800px;
      margin: 0 auto;
      background: var(--white);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow-lg);
      padding: 48px;
      text-align: center;
    }

    .locator-form {
      display: flex;
      gap: 12px;
      max-width: 500px;
      margin: 32px auto 0;
    }

    .locator-input {
      flex: 1;
      padding: 14px 20px;
      border: 2px solid #e0e7e1;
      border-radius: var(--radius-lg);
      font-family: 'Poppins', sans-serif;
      font-size: 1rem;
      transition: border-color 0.25s;
    }

    .locator-input:focus {
      outline: none;
      border-color: var(--green-primary);
    }

    .locator-btn {
      padding: 14px 28px;
      background: var(--green-primary);
      color: var(--white);
      border: none;
      border-radius: var(--radius-lg);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      cursor: pointer;
      transition: background 0.25s;
    }

    .locator-btn:hover {
      background: var(--green-dark);
    }

    .store-results {
      margin-top: 32px;
      text-align: left;
      display: none;
    }

    .store-results.visible {
      display: block;
    }

    .store-result-item {
      padding: 20px;
      border: 1px solid #e0e7e1;
      border-radius: var(--radius-md);
      margin-bottom: 12px;
      transition: all 0.25s;
    }

    .store-result-item:hover {
      border-color: var(--green-primary);
      box-shadow: var(--shadow-sm);
    }

    .store-name {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1.1rem;
      color: var(--green-primary);
      margin-bottom: 4px;
    }

    .store-address {
      font-size: 0.9rem;
      color: var(--text-muted);
      margin-bottom: 8px;
    }

    .store-meta {
      display: flex;
      gap: 20px;
      font-size: 0.85rem;
    }

    .store-hours {
      color: var(--text-muted);
    }

    .store-distance {
      color: var(--orange-accent);
      font-weight: 600;
    }

    /* Newsletter */
    .newsletter {
      padding: 80px 24px;
      background: var(--green-primary);
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .newsletter::before {
      content: '';
      position: absolute;
      top: -100px;
      right: -100px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 70%);
      border-radius: 50%;
    }

    .newsletter-inner {
      max-width: 600px;
      margin: 0 auto;
      position: relative;
      z-index: 1;
    }

    .newsletter h2 {
      font-size: 2.25rem;
      color: var(--white);
      margin-bottom: 12px;
    }

    .newsletter p {
      color: rgba(255,255,255,0.85);
      margin-bottom: 32px;
      font-size: 1.05rem;
    }

    .newsletter-form {
      display: flex;
      gap: 12px;
      max-width: 480px;
      margin: 0 auto;
    }

    .newsletter-input {
      flex: 1;
      padding: 14px 20px;
      border: none;
      border-radius: var(--radius-lg);
      font-family: 'Poppins', sans-serif;
      font-size: 1rem;
    }

    .newsletter-btn {
      padding: 14px 28px;
      background: var(--orange-accent);
      color: var(--white);
      border: none;
      border-radius: var(--radius-lg);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      cursor: pointer;
      transition: all 0.25s;
    }

    .newsletter-btn:hover {
      background: var(--orange-dark);
      transform: translateY(-2px);
    }

    .newsletter-confirmation {
      display: none;
      background: rgba(255,255,255,0.15);
      border-radius: var(--radius-md);
      padding: 16px 24px;
      color: var(--white);
      margin-top: 20px;
    }

    .newsletter-confirmation.visible {
      display: block;
    }

    /* Footer */
    .footer {
      background: var(--text-dark);
      color: var(--white);
      padding: 64px 24px 32px;
    }

    .footer-inner {
      max-width: 1280px;
      margin: 0 auto;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr 1fr 1fr 1fr;
      gap: 48px;
      margin-bottom: 48px;
    }

    .footer-brand p {
      color: rgba(255,255,255,0.7);
      margin-top: 16px;
      font-size: 0.95rem;
      max-width: 280px;
    }

    .footer-title {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      margin-bottom: 20px;
      font-size: 1rem;
    }

    .footer-links {
      list-style: none;
    }

    .footer-links li {
      margin-bottom: 12px;
    }

    .footer-links a {
      color: rgba(255,255,255,0.7);
      text-decoration: none;
      font-size: 0.9rem;
      transition: color 0.2s;
    }

    .footer-links a:hover {
      color: var(--orange-accent);
    }

    .footer-social {
      display: flex;
      gap: 16px;
      margin-top: 20px;
    }

    .footer-social a {
      width: 40px;
      height: 40px;
      background: rgba(255,255,255,0.1);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 0.25s;
    }

    .footer-social a:hover {
      background: var(--orange-accent);
    }

    .footer-social svg {
      width: 20px;
      height: 20px;
      fill: var(--white);
    }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 32px;
      text-align: center;
      color: rgba(255,255,255,0.5);
      font-size: 0.9rem;
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .hero-inner {
        grid-template-columns: 1fr;
        text-align: center;
      }

      .hero-content {
        order: 1;
      }

      .hero-image {
        order: 2;
      }

      .hero-subtitle {
        margin: 0 auto 36px;
      }

      .hero-buttons {
        justify-content: center;
      }

      .hero-image-main {
        height: 300px;
      }

      .stats-inner {
        grid-template-columns: repeat(2, 1fr);
      }

      .product-card {
        flex: 0 0 calc(33.333% - 16px);
      }

      .categories-grid {
        grid-template-columns: repeat(3, 1fr);
      }

      .seasonal-grid {
        grid-template-columns: 1fr;
      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (max-width: 768px) {
      .nav {
        display: none;
      }

      .mobile-menu-btn {
        display: block;
      }

      .hero {
        padding: 120px 24px 60px;
      }

      .hero h1 {
        font-size: 2.5rem;
      }

      .stats-inner {
        grid-template-columns: repeat(2, 1fr);
        gap: 24px;
      }

      .stat-number {
        font-size: 2.25rem;
      }

      .product-card {
        flex: 0 0 calc(50% - 12px);
        min-width: 200px;
      }

      .carousel-viewport {
        margin: 0 16px;
      }

      .carousel-btn {
        width: 40px;
        height: 40px;
      }

      .categories-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .category-card {
        height: 160px;
      }

      .locator-card {
        padding: 32px 24px;
      }

      .locator-form {
        flex-direction: column;
      }

      .newsletter-form {
        flex-direction: column;
      }

      .footer-grid {
        grid-template-columns: 1fr;
        gap: 32px;
      }
    }

    @media (max-width: 480px) {
      .hero h1 {
        font-size: 2rem;
