  <script>
    // Featured Products Carousel
    const carouselTrack = document.getElementById('carouselTrack');
    const prevBtn = document.querySelector('.carousel-btn.prev');
    const nextBtn = document.querySelector('.carousel-btn.next');
    const productCards = document.querySelectorAll('.product-card');

    let currentIndex = 0;
    const cardWidth = productCards[0].offsetWidth + 24; // card width + gap
    const visibleCards = () => {
      const viewportWidth = document.querySelector('.carousel-viewport').offsetWidth;
      return Math.floor(viewportWidth / cardWidth);
    };

    function updateCarousel() {
      const maxIndex = productCards.length - visibleCards();
      currentIndex = Math.max(0, Math.min(currentIndex, maxIndex));
      const offset = currentIndex * cardWidth;
      carouselTrack.style.transform = `translateX(-${offset}px)`;
    }

    prevBtn.addEventListener('click', () => {
      currentIndex = Math.max(0, currentIndex - 1);
      updateCarousel();
    });

    nextBtn.addEventListener('click', () => {
      const maxIndex = productCards.length - visibleCards();
      currentIndex = Math.min(maxIndex, currentIndex + 1);
      updateCarousel();
    });

    // Handle window resize
    let resizeTimeout;
    window.addEventListener('resize', () => {
      clearTimeout(resizeTimeout);
      resizeTimeout = setTimeout(updateCarousel, 100);
    });

    // Store Locator
    const locatorForm = document.getElementById('locatorForm');
    const storeResults = document.getElementById('storeResults');

    locatorForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const zipInput = document.getElementById('zipInput');
      if (zipInput.value.length === 5) {
        storeResults.classList.add('visible');
        storeResults.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    });

    // Newsletter Signup
    const newsletterForm = document.getElementById('newsletterForm');
    const newsletterConfirmation = document.getElementById('newsletterConfirmation');

    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const emailInput = document.getElementById('emailInput');
      if (emailInput.value && emailInput.validity.valid) {
        newsletterConfirmation.classList.add('visible');
        newsletterForm.reset();
      }
    });

    // Smooth scroll for navigation
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
          target.scrollIntoView({ behavior: 'smooth' });
        }
      });
    });
  </script>
